-- Fusion des deux listes de sources de la veille automatique (12/09/2026) --
-- ---------------------------------------------------------------------------
-- Jusqu'ici, la veille consultait deux listes séparées : les 14 lignes de
-- affut_sources_suivies (écran « Sources », visitées à CHAQUE exécution) et
-- un catalogue statique de 137 revues/bulletins dans
-- apps/affut/documents/brief-veille.md (visité une fois par mois seulement,
-- jamais éditable depuis l'app). Confusion constatée par l'utilisateur (« la
-- routine n'annonce que 14 sources suivies, on en avait pourtant écrit
-- beaucoup plus ») : les deux listes portaient presque le même nom pour des
-- rôles différents.
--
-- Cette migration fait de affut_sources_suivies la SEULE liste d'adresses à
-- consulter, hebdomadaires et mensuelles confondues, en ajoutant la
-- périodicité comme donnée plutôt que comme deux mécanismes séparés :
-- - `periodicite` : 'hebdomadaire' (visitée à chaque exécution, comme avant
--   pour les 14 sources d'origine) ou 'mensuelle' (visitée seulement à
--   l'exécution qui tombe dans la 1re semaine du mois — logique reprise de
--   la section « Revues et bulletins naturalistes » du brief) ;
-- - `notes` : le reliquat texte libre du catalogue (éditeur, thématique,
--   accès, périodicité éditoriale, remarques) — informationnel, jamais lu
--   par la mécanique de filtrage.
--
-- Import des 137 revues du catalogue en lignes `periodicite = 'mensuelle'`
-- (générées depuis brief-veille.md, voir le commit associé) — la section
-- correspondante du brief est retirée dans la foulée pour ne plus avoir
-- qu'un seul endroit où cette liste existe.

alter table affut_sources_suivies
  add column if not exists periodicite text not null default 'hebdomadaire',
  add column if not exists notes text not null default '';

alter table affut_sources_suivies
  drop constraint if exists affut_sources_suivies_periodicite_check;

alter table affut_sources_suivies
  add constraint affut_sources_suivies_periodicite_check
  check (periodicite in ('hebdomadaire', 'mensuelle'));

-- Les 14 sources existantes n'ont pas de valeur explicite : le défaut
-- 'hebdomadaire' ci-dessus leur convient déjà (comportement inchangé pour
-- elles), rien à rétrofiter.

on conflict (id) do nothing;
